import sys

def is_prime(n):
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def solve():
    line = sys.stdin.read().strip()
    if line:
        print("YES" if is_prime(int(line)) else "NO")

if __name__ == '__main__':
    solve()

