#include <stdio.h>
#include <stdlib.h>

long long gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    long long a, b;
    if (scanf("%lld %lld", &a, &b) == 2) {
        if (a == 0) {
            printf("0 1\n");
            return 0;
        }
        long long g = gcd(llabs(a), llabs(b));
        a /= g;
        b /= g;
        if (b < 0) {
            a = -a;
            b = -b;
        }
        printf("%lld %lld\n", a, b);
    }
    return 0;
}

