import sys

def solve():
    line = sys.stdin.read().strip()
    if not line:
        return
    n = int(line)
    factors = []
    i = 2
    while i * i <= n:
        while n % i == 0:
            factors.append(str(i))
            n //= i
        i += 1
    if n > 1:
        factors.append(str(n))
    print(" ".join(factors))

if __name__ == '__main__':
    solve()

